import{_ as r,o as e,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Mini FOSS Universe","description":"","frontmatter":{},"headers":[],"relativePath":"mini-foss-universe.md","filePath":"mini-foss-universe.md"}'),s={name:"mini-foss-universe.md"};function d(i,t,n,l,c,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="mini-foss-universe" tabindex="-1">Mini FOSS Universe <a class="header-anchor" href="#mini-foss-universe" aria-label="Permalink to &quot;Mini FOSS Universe&quot;">​</a></h1><p>The <strong>Tradeboard Mini FOSS Universe</strong> is a curated collection of open-source projects, SDKs, libraries, and integrations that extend the Tradeboard ecosystem across languages, platforms, and workflows.</p><p>Whether you’re building trading strategies, data pipelines, dashboards, or AI-driven systems, Tradeboard provides open-source tools that integrate seamlessly into every modern trading workflow.</p><p>This ecosystem is designed to be:</p><ul><li><strong>Modular</strong>: use only what you need</li><li><strong>Extensible</strong>: customize and build on top of existing components</li><li><strong>Language-agnostic</strong>: work in the stack you’re most comfortable with</li><li><strong>Production-ready</strong>: stable APIs with long-term support</li></ul><p>All projects in the Mini FOSS Universe are community-driven and built with real-world trading and automation use cases in mind.</p><hr><h3 id="core-project" tabindex="-1">Core Project <a class="header-anchor" href="#core-project" aria-label="Permalink to &quot;Core Project&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Repository</th></tr></thead><tbody><tr><td><strong>Tradeboard Core</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></td></tr></tbody></table><p><strong>Tradeboard Core</strong> is the central heartbeat of the ecosystem, powering the API service, authentication, routing, and platform logic.<br><br> All SDKs, libraries, and integrations interact with the API endpoints exposed by Tradeboard Core.</p><hr><h3 id="libraries-and-sdks" tabindex="-1">Libraries and SDKs <a class="header-anchor" href="#libraries-and-sdks" aria-label="Permalink to &quot;Libraries and SDKs&quot;">​</a></h3><p>Tradeboard provides official SDKs and libraries to help developers interact with the Tradeboard API without making raw HTTP calls. These packages handle authentication, request formatting, and response parsing, allowing you to focus on strategy and logic.</p><h4 id="api-version" tabindex="-1">API Version <a class="header-anchor" href="#api-version" aria-label="Permalink to &quot;API Version&quot;">​</a></h4><p>The current stable version of the Tradeboard API is <strong>v1</strong>.</p><ul><li>All SDKs and integrations listed below are built against <strong>API v1</strong></li><li>v1 is stable, backward-compatible, and recommended for production use</li><li>Future versions will be introduced without breaking existing v1 integrations</li></ul><hr><h3 id="sdks" tabindex="-1">SDKs <a class="header-anchor" href="#sdks" aria-label="Permalink to &quot;SDKs&quot;">​</a></h3><p>SDKs are officially supported client packages intended for application development and system-level integrations.</p><table tabindex="0"><thead><tr><th>Language / Platform</th><th>Repository</th></tr></thead><tbody><tr><td>Python</td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-python-library" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-python-library</a></td></tr><tr><td>Node.js</td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-node" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-node</a></td></tr><tr><td>Java</td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-java" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-java</a></td></tr><tr><td>RUST</td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-rust" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-rust</a></td></tr><tr><td>.NET / C#</td><td><a href="https://github.com/wesoftcorp/tradeboard-docs.NET" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs.NET</a></td></tr><tr><td>Go</td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-go" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-go</a></td></tr></tbody></table><hr><h3 id="libraries-and-platform-integrations" tabindex="-1">Libraries and Platform Integrations <a class="header-anchor" href="#libraries-and-platform-integrations" aria-label="Permalink to &quot;Libraries and Platform Integrations&quot;">​</a></h3><p>These libraries and tools extend Tradeboard support to popular trading platforms, analysis tools, and user interfaces.</p><table tabindex="0"><thead><tr><th>Platform / Tool</th><th>Repository</th></tr></thead><tbody><tr><td><strong>Excel Add-in</strong></td><td><a href="https://github.com/marketcalls/Tradeboard-Excel" target="_blank" rel="noreferrer">https://github.com/marketcalls/Tradeboard-Excel</a></td></tr><tr><td><strong>Amibroker Plugin</strong></td><td><a href="https://github.com/marketcalls/TradeboardPlugin" target="_blank" rel="noreferrer">https://github.com/marketcalls/TradeboardPlugin</a></td></tr><tr><td><strong>Backtrader Integration</strong></td><td><a href="https://github.com/p2c2e/tradeboard-backtrader" target="_blank" rel="noreferrer">https://github.com/p2c2e/tradeboard-backtrader</a></td></tr><tr><td><strong>PineTS</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-pinets" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-pinets</a></td></tr><tr><td><strong>Tradeboard Charts</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-charts" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-charts</a></td></tr><tr><td><strong>AlgoMirror</strong></td><td><a href="https://github.com/marketcalls/algomirror" target="_blank" rel="noreferrer">https://github.com/marketcalls/algomirror</a></td></tr><tr><td><strong>Tradeboard chart</strong></td><td><a href="https://github.com/crypt0inf0/tradeboard-chart" target="_blank" rel="noreferrer">https://github.com/crypt0inf0/tradeboard-chart</a></td></tr><tr><td><strong>Tradeboard Heatmap</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-heatmap" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-heatmap</a></td></tr><tr><td><strong>Historify (standalone)</strong></td><td><a href="https://github.com/marketcalls/historify" target="_blank" rel="noreferrer">https://github.com/marketcalls/historify</a></td></tr><tr><td><strong>Tradeboard Helm Chart</strong></td><td><a href="https://github.com/p2c2e/tradeboard_helm" target="_blank" rel="noreferrer">https://github.com/p2c2e/tradeboard_helm</a></td></tr><tr><td><strong>MCP / AI Agents</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-mcp" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-mcp</a></td></tr><tr><td><strong>Tradeboard Mobile (Flutter)</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-mobile" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-mobile</a></td></tr><tr><td><strong>Web Portal</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-webpage" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-webpage</a></td></tr><tr><td><strong>Chrome Extension</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-chrome" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-chrome</a></td></tr><tr><td><strong>Fast Scalper (Rust + Tauri)</strong></td><td><a href="https://github.com/marketcalls/fastscalper-tauri" target="_blank" rel="noreferrer">https://github.com/marketcalls/fastscalper-tauri</a></td></tr></tbody></table><p>Two of these deserve a note, because the feature also exists inside Tradeboard Core:</p><ul><li><strong>MCP.</strong> Core ships its own Model Context Protocol server at <code>mcp/mcpserver.py</code>, with a local stdio transport and an optional OAuth-protected remote HTTP transport. The separate <code>tradeboard-mcp</code> repository is the older standalone server and its documentation. Prefer the built-in one, and see <a href="./mcp/README.html">MCP</a>.</li><li><strong>Historify.</strong> Core ships Historify as a built-in DuckDB history store at <code>/historify</code>. The standalone <code>historify</code> repository is the separate full-stack application. See <a href="./new-features/historify.html">Historify</a>.</li></ul><hr><h3 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h3><p>Skills are installable instruction packages that teach an AI coding agent how to drive Tradeboard. They install through <a href="https://github.com/vercel-labs/skills" target="_blank" rel="noreferrer">skills.sh</a> with <code>npx skills add &lt;repo&gt;</code> and work across Claude Code, Cursor, Codex, OpenCode, Cline, Windsurf, and other agents.</p><table tabindex="0"><thead><tr><th>Skill package</th><th>Repository</th></tr></thead><tbody><tr><td><strong>Tradeboard Skills (execution)</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-skills" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-skills</a></td></tr><tr><td><strong>Indicator Skills</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-indicator-skills" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-indicator-skills</a></td></tr><tr><td><strong>VectorBT Backtesting Skills</strong></td><td><a href="https://github.com/marketcalls/vectorbt-backtesting-skills" target="_blank" rel="noreferrer">https://github.com/marketcalls/vectorbt-backtesting-skills</a></td></tr><tr><td><strong>Execution Skills (dual-mode)</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-execution-skills" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-execution-skills</a></td></tr><tr><td><strong>Claude Code Plugin</strong></td><td><a href="https://github.com/wesoftcorp/tradeboard-docs-claude-plugin" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs-claude-plugin</a></td></tr></tbody></table><p>See <a href="./skills/README.html">Skills</a> for what each package installs and how to use it.</p><hr><h3 id="documentation-and-examples" tabindex="-1">Documentation and Examples <a class="header-anchor" href="#documentation-and-examples" aria-label="Permalink to &quot;Documentation and Examples&quot;">​</a></h3><p>Each SDK and integration has dedicated documentation that includes installation steps, configuration guidance, and working examples:</p><ul><li>Python: <a href="https://docs.algo.wesoftcorp.com/trading-platform/python" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/python</a></li><li>Node.js: <a href="https://docs.algo.wesoftcorp.com/trading-platform/nodejs" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/nodejs</a></li><li>Java: <a href="https://docs.algo.wesoftcorp.com/trading-platform/java" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/java</a></li><li>.NET: <a href="https://docs.algo.wesoftcorp.com/trading-platform/.net" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/.net</a></li><li>Go: <a href="https://docs.algo.wesoftcorp.com/trading-platform/go" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/go</a></li><li>RUST: <a href="https://docs.algo.wesoftcorp.com/trading-platform/rust" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/rust</a></li><li>Excel: <a href="https://docs.algo.wesoftcorp.com/trading-platform/excel" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/excel</a></li><li>Amibroker Plugin: <a href="https://docs.algo.wesoftcorp.com/trading-platform/amibroker/amibroker-plugin" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/amibroker/amibroker-plugin</a></li><li>Chrome Extension: <a href="https://docs.algo.wesoftcorp.com/trading-platform/chrome-extension" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/chrome-extension</a></li><li>MCP / AI Agents: <a href="https://docs.algo.wesoftcorp.com/mcp" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/mcp</a></li><li>Skills: <a href="https://docs.algo.wesoftcorp.com/skills" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/skills</a></li></ul><hr><h3 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h3><p>The Mini FOSS Universe reflects Tradeboard’s core philosophy:<br><strong>open standards, transparent design, and tools that adapt to how traders actually work</strong>.</p><p>You can use these projects independently, combine them into larger systems, or fork and extend them to suit your own trading infrastructure.</p>',39)])])}const b=r(s,[["render",d]]);export{g as __pageData,b as default};
